<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';$user=require_role('admin');
require_once __DIR__.'/../includes/admin_reports.php';require_once __DIR__.'/../includes/dashboard.php';
try {$range=report_date_range($_GET['start']??'',$_GET['end']??'');}
catch (InvalidArgumentException $exception) {http_response_code(400);exit(e($exception->getMessage()));}
try {$report=admin_report_data($range);}catch (Throwable $exception) {error_log('Admin reports failed. Code: '.$exception->getCode());http_response_code(503);exit('Reports are temporarily unavailable. Please try again later.');}
$cards=[['Registered users','users','By registration date'],['Published donations','donations','By publication date'],
    ['Submitted requests','requests','By request date'],['Volunteer assignments','assignments','By assignment date'],
    ['Recorded deliveries','deliveries','By delivery timestamp'],['Confirmed receipts','receipts','By receipt confirmation date']];
$sections=[['Donation statuses','donations','donations','Published donations in this period, grouped by current status. Overdue uncollected food appears as expired.'],
    ['Request decisions','requests','requests','Requests submitted in this period, grouped by current decision.'],
    ['Collection task statuses','tasks','assignments','Tasks assigned in this period, grouped by current status.'],
    ['Registered users by role','users','users','Users registered in this period, grouped by role.']];
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Reports and statistics | <?= e(APP_NAME) ?></title><link rel="stylesheet" href="<?= e(app_url('assets/css/bootstrap.min.css')) ?>"><link rel="stylesheet" href="<?= e(app_url('assets/css/style.css')) ?>"></head><body>
<?php $navigationUser=$user;require __DIR__.'/../includes/header.php'; ?><main class="container py-5" id="main-content"><div class="row g-4"><?php $adminPage='reports';require __DIR__.'/../includes/admin_sidebar.php'; ?>
<section class="col-lg-9" aria-labelledby="reports-heading"><div class="dashboard-welcome mb-4"><h1 class="h2" id="reports-heading">Reports and statistics</h1><p class="text-secondary">Review community activity and confirmed food receipts. All dates use Sri Lanka time.</p></div>
<form method="get" class="account-card mb-4"><div class="row g-3"><div class="col-md-4"><label class="form-label" for="start">Start date</label><input class="form-control" type="date" name="start" id="start" value="<?= e($range['start']) ?>" min="1000-01-01" max="9998-12-31"></div><div class="col-md-4"><label class="form-label" for="end">End date</label><input class="form-control" type="date" name="end" id="end" value="<?= e($range['end']) ?>" min="1000-01-01" max="9998-12-31"></div><div class="col-md-4 d-flex align-items-end gap-2"><button class="btn btn-community">Apply dates</button><a class="btn btn-quiet" href="<?= e(app_url('admin/reports.php')) ?>">All time</a></div></div><p class="form-text mt-3 mb-0">Choose both dates or leave both empty for all time. The end date is included.</p></form>
<p class="text-secondary"><?= $range['start']===''?'All-time activity':e($range['start'].' to '.$range['end']).' (inclusive)' ?>. Each card uses the event date shown beneath it. Status breakdowns show current statuses, not historical snapshots.</p>
<div class="row g-3 mb-4"><?php foreach ($cards as [$label,$key,$note]): ?><div class="col-sm-6 col-xl-4"><article class="dashboard-stat"><h2><?= e($label) ?></h2><strong><?= e(number_format($report['totals'][$key])) ?></strong><p><?= e($note) ?></p></article></div><?php endforeach; ?></div>
<div class="row g-4"><?php foreach ($sections as [$heading,$key,$totalKey,$note]): ?><div class="col-xl-6"><section class="account-card h-100"><h2 class="h5"><?= e($heading) ?></h2><p class="small text-secondary"><?= e($note) ?></p><?php if (!$report[$key]): ?><p class="mb-0">No records in this period.</p><?php else: ?><table class="table align-middle mb-0"><caption class="visually-hidden"><?= e($heading) ?></caption><thead><tr><th scope="col"><?= $key==='users'?'Role':'Status' ?></th><th scope="col" class="text-end">Count</th></tr></thead><tbody><?php foreach ($report[$key] as $row): ?><tr><th scope="row" class="fw-normal"><?= $key==='users'?e(ucfirst($row['label'])):status_badge($row['label']) ?></th><td class="text-end"><?= e(number_format((int)$row['total'])) ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></section></div><?php endforeach; ?></div>
<section class="account-card mt-4"><h2 class="h5">Food received by unit</h2><p class="small text-secondary">Completed donations confirmed in this period. Quantities are kept separate by unit.</p><?php if (!$report['received_quantities']): ?><p class="mb-0">No confirmed food receipts in this period.</p><?php else: ?><div class="table-responsive"><table class="table align-middle mb-0"><caption class="visually-hidden">Confirmed food quantities by unit.</caption><thead><tr><th scope="col">Unit</th><th scope="col">Donations</th><th scope="col">Quantity received</th></tr></thead><tbody><?php foreach ($report['received_quantities'] as $row): ?><tr><th scope="row"><?= e(ucfirst($row['label'])) ?></th><td><?= e(number_format((int)$row['donations'])) ?></td><td><?= e(rtrim(rtrim(number_format((float)$row['quantity'],2,'.',','),'0'),'.').' '.$row['label']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
</section></div></main><?php require __DIR__.'/../includes/footer.php'; ?></body></html>
